Status validate_terminal_trigger(const CommonStore& common,const MilitaryState& military,const ExactTrainingReadContext& x,const DynamicMilitaryTrainingFact2& f,const SourceRef& cause,const WorldMoment& at,const StableId& code){return status([&]{
 if(code=="MilitaryTrainingCancelled"){if(cause.domain!="military"||cause.kind!="military_training_cancelled")fail("ExactTrainingCancellationSourceRequired",f.id);header(common,cause);return;}
 if(code=="MilitaryTrainingUnsupplied"){const Integer next=Integer(f.lessons.size())+1;if(next>4||!same_moment(at,gate(f,next,x.budget),x.budget))fail("ExactTrainingSupplyFailureGateMismatch",f.id);auto selected=take(read_original_training_closing_supply_gate(common,military,x,f,next));const auto* food=find(military.supply_facts,selected.supply_fact_ref.id);if(!same_source(cause,selected.supply_fact_ref)||!food||food->shortage<=0)fail("ExactTrainingUnsuppliedSourceRequired",f.id);return;}
 take(x.original.validate_training_terminal_cause(f,cause,at,code));
});}
Status validate_fact_history(const CommonStore& common,const MilitaryState& military,const MilitaryActionTimeState& state,const ExactTrainingReadContext& x,const DynamicMilitaryTrainingFact2& f,const ActionElapsedState& entry,bool pending){return status([&]{
 bound(common,military,x);header(common,start_ref(f.id));if(f.id.empty()||find(military.training_facts,f.id)||f.actor_id!=f.terms.actor_id||f.rule_version!=2||f.elapsed_source_ref.action_ref!=f.id||f.work_binding_ref.action_id!=f.id||f.work_binding_ref.action_kind!="military_train"||!same_source(f.work_binding_ref.source_owner_ref,start_ref(f.id))||f.lessons.size()>4)fail("ExactTrainingOriginalIdentityMismatch",f.id);
 const auto& t=f.terms;std::set<StableId> fit(t.fit_ids.begin(),t.fit_ids.end()),people(t.participants.begin(),t.participants.end());if(t.duration!=4||t.fee!=150||fit.empty()||fit.size()!=t.fit_ids.size()||people.size()!=t.participants.size()||!people.count(t.actor_id)||!people.count(t.commander_actor_id)||fit.count(StableId{})||people.count(StableId{})||!std::is_sorted(t.fit_ids.begin(),t.fit_ids.end())||!std::is_sorted(t.participants.begin(),t.participants.end())||t.fatigue_before<0||t.fatigue_before>100||t.fatigue_per_tick<0||t.fatigue_per_tick>20||t.payer_wallet_id==t.recipient_wallet_id)fail("InvalidMilitaryTrainingTerms",f.id);
 take(original_military_training_after(t,0,{}));take(x.original.validate_training_acceptance(f));
 if(entry.action_ref!=f.id||entry.execution_source_ref!=f.id||entry.duration_definition_ref!="military_train_original_4_half_days_v2"||entry.owner_cost_state_ref!=f.id||entry.owner_work_remainder||!same_moment(entry.started_at,f.started_at,x.budget)||compare(entry.required_units.value,take(fixed_duration_work_units(4,x.scale.units_per_half_day,x.budget)).value,x.budget)||take(compare_world_moments(entry.last_settled_at,f.started_at,x.budget))<0||take(compare_world_moments(entry.last_settled_at,take(x.clock.read_current_moment()),x.budget))>0)fail("ExactTrainingElapsedBindingMismatch",f.id);
 const auto actual_credit=take(duration_to_scale_units(take(elapsed_world_duration(f.started_at,entry.last_settled_at,x.budget)),x.scale.units_per_half_day,x.budget));if(compare(actual_credit.value,entry.credited_units.value,x.budget)||compare(entry.credited_units.value,entry.required_units.value,x.budget)>0)fail("ExactTrainingDiscontinuousService",f.id);
 WorldMoment cursor=f.started_at;std::set<StableId> owned_spans,owned_witnesses;
 for(const auto& row:state.training_participation_spans.rows())if(row.second.action_ref==f.id){const auto& span=row.second;header(common,{"military","military_training_participation",row.first});if(!same_source(span.terms_source_ref,start_ref(f.id))||!same_moment(span.from,cursor,x.budget)||take(compare_world_moments(span.to,span.from,x.budget))<=0||take(compare_world_moments(span.to,entry.last_settled_at,x.budget))>0||!source_valid(span.actual_participant_selection_ref)||span.unit_and_occupation_source_refs.empty())fail("ExactTrainingParticipationCoverageMismatch",row.first);take(x.original.validate_actual_training_participation(f,span));owned_spans.insert(row.first);cursor=span.to;
  auto witness_cursor=span.from;for(const auto& wr:state.training_period_witnesses.rows())if(wr.second.action_ref==f.id&&std::any_of(wr.second.actual_participation_span_refs.begin(),wr.second.actual_participation_span_refs.end(),[&](const auto& ref){return same_source(ref,{"military","military_training_participation",row.first});})){
   const auto& w=wr.second;header(common,{"military","military_training_period_witness",wr.first});if(!owned_witnesses.insert(wr.first).second||w.actual_participation_span_refs.size()!=1||!same_moment(w.intersection_from,witness_cursor,x.budget)||take(compare_world_moments(w.intersection_to,w.intersection_from,x.budget))<=0||take(compare_world_moments(w.intersection_to,span.to,x.budget))>0)fail("ExactTrainingPeriodWitnessCoverageMismatch",wr.first);
   auto p=take(x.periods.read_training_period(w.intersection_from.half_day_tick));period(p,w.intersection_from.half_day_tick,x.budget);if(p.period_ref!=w.period_ref||!same_source(p.original_opening.source_ref,w.opening_receipt_ref)||take(compare_world_moments(w.intersection_to,take(normalize_world_moment(p.to_tick,integer(0,x.budget),x.budget)),x.budget))>0)fail("ExactTrainingPeriodWitnessMismatch",wr.first);
   // This producer does not claim historical full-period feeding. A foreign
   // observed-supply proof must not be silently accepted as its own payload.
   if(w.observed_supply_ref)fail("ExactTrainingUnexpectedObservedSupply",wr.first);witness_cursor=w.intersection_to;
  }if(!same_moment(witness_cursor,span.to,x.budget))fail("ExactTrainingPeriodWitnessMissing",row.first);
 }
 if(!same_moment(cursor,entry.last_settled_at,x.budget))fail("ExactTrainingParticipationSpanMissing",f.id);
 for(const auto& w:state.training_period_witnesses.rows())if(w.second.action_ref==f.id&&!owned_witnesses.count(w.first))fail("OrphanTrainingPeriodWitness",w.first);
 if(bool(t.drill)!=bool(f.drill))fail("ExactTrainingDrillTermsMismatch",f.id);
 if(f.drill){const auto& d=*f.drill;take(validate_original_training_drill_identity(x.catalog,t,f.actor_id,f.id,d.origin_seed,d.origin_state,d.challenge));if(d.phase==DynamicTrainingDrillPhase::pending){if(f.phase!=DynamicMilitaryTrainingPhase::started||!f.lessons.empty()||d.frozen_at||d.performance_bp)fail("ExactTrainingDrillConsumptionMismatch",f.id);}else if(d.phase==DynamicTrainingDrillPhase::closed){if(f.phase!=DynamicMilitaryTrainingPhase::completed||!f.lessons.empty()||d.frozen_at||d.performance_bp||d.challenge.phase!="completed")fail("ExactTrainingDrillConsumptionMismatch",f.id);}else if(d.phase==DynamicTrainingDrillPhase::frozen){if(f.lessons.empty()||!d.frozen_at||!same_moment(*d.frozen_at,gate(f,1,x.budget),x.budget)||!d.performance_bp||!d.challenge.result||d.challenge.phase!="completed"||*d.performance_bp!=d.challenge.result->performance_bp)fail("ExactTrainingDrillConsumptionMismatch",f.id);}else fail("UnknownExactTrainingDrillPhase",f.id);}
 Integer training=t.training_before,fatigue=t.fatigue_before;std::set<StableId> fees;
 for(std::size_t index=0;index<f.lessons.size();++index){const auto& l=f.lessons[index];const Integer i=Integer(index)+1;if(l.ordinal!=i||!same_moment(l.service_from,gate(f,i-1,x.budget),x.budget)||!same_moment(l.closed_at,gate(f,i,x.budget),x.budget)||take(compare_world_moments(l.closed_at,entry.last_settled_at,x.budget))>0||compare(l.gate_work_units.value,take(fixed_duration_work_units(i,x.scale.units_per_half_day,x.budget)).value,x.budget)||l.fee_paid!=take(original_military_training_fee(i))||l.training_before!=training||l.fatigue_before!=fatigue||l.training_after!=take(original_military_training_after(t,i,f.drill?f.drill->performance_bp:std::nullopt))||l.fatigue_after!=military_training_progress::unit_fatigue(t,i)||l.fee_effect_ref.domain!="military"||l.fee_effect_ref.kind!="military_training_lesson"||!fees.insert(l.fee_effect_ref.id).second)fail("ExactTrainingLessonMismatch",f.id);
  header(common,l.fee_effect_ref);auto supply=take(read_original_training_closing_supply_gate(common,military,x,f,i));valid_gate(l.closing_supply_gate,supply,f.id,x.budget);const auto* food=find(military.supply_facts,supply.supply_fact_ref.id);if(!food)fail("MilitaryTrainingSupplyRequired",f.id);take(validate_original_military_training_supply(*food,x.catalog,t,supply.period_to_tick));
  std::vector<SourceRef> spans,witnesses;for(const auto& row:state.training_participation_spans.rows())if(row.second.action_ref==f.id&&take(compare_world_moments(row.second.from,l.service_from,x.budget))>=0&&take(compare_world_moments(row.second.to,l.closed_at,x.budget))<=0)spans.push_back({"military","military_training_participation",row.first});for(const auto& row:state.training_period_witnesses.rows())if(row.second.action_ref==f.id&&take(compare_world_moments(row.second.intersection_from,l.service_from,x.budget))>=0&&take(compare_world_moments(row.second.intersection_to,l.closed_at,x.budget))<=0)witnesses.push_back({"military","military_training_period_witness",row.first});references(l.participation_span_refs,spans,f.id);references(l.period_witness_refs,witnesses,f.id);if(spans.empty()||witnesses.empty())fail("ExactTrainingLessonServiceMissing",f.id);
  if(bool(l.drill_frozen_source_ref)!=bool(f.drill))fail("ExactTrainingDrillFreezeSourceMismatch",f.id);if(l.drill_frozen_source_ref){const auto& ref=*l.drill_frozen_source_ref;header(common,ref);const auto* frozen=state.drill_freeze_sources.find(ref.id);if(ref.domain!="military"||ref.kind!="military_training_drill_frozen"||!frozen||frozen->action_ref!=f.id||!same_moment(frozen->frozen_at,gate(f,1,x.budget),x.budget)||!same_source(frozen->first_lesson_ref,f.lessons.front().fee_effect_ref)||frozen->performance_bp!=*f.drill->performance_bp)fail("ExactTrainingDrillFreezeSourceMismatch",f.id);}
  take(x.original.validate_training_learning_result(f,l));training=l.training_after;fatigue=l.fatigue_after;
 }
 if(f.phase==DynamicMilitaryTrainingPhase::started){if(f.completed_at||f.terminal_code||f.terminal_source_ref||f.completion_application_source||f.success||f.lessons.size()>=4)fail("ExactTrainingPrematureTerminal",f.id);const auto next=gate(f,Integer(f.lessons.size())+1,x.budget);const int order=take(compare_world_moments(entry.last_settled_at,next,x.budget));if(order>0||(!pending&&order==0))fail("ExactTrainingUnconsumedLesson",f.id);}
 else if(f.phase==DynamicMilitaryTrainingPhase::completed){if(!f.completed_at||!f.terminal_source_ref||!same_moment(*f.completed_at,entry.last_settled_at,x.budget)||f.success!=(f.lessons.size()==4&&!f.terminal_code))fail("ExactTrainingTerminalMismatch",f.id);if(f.success){if(!same_source(*f.terminal_source_ref,f.lessons.back().fee_effect_ref)||!same_moment(*f.completed_at,gate(f,4,x.budget),x.budget))fail("ExactTrainingCompletionSourceMismatch",f.id);}else{if(!f.terminal_code||f.terminal_code->empty())fail("ExactTrainingFailureCauseRequired",f.id);take(validate_terminal_trigger(common,military,x,f,*f.terminal_source_ref,*f.completed_at,*f.terminal_code));}}
 else fail("UnknownExactTrainingPhase",f.id);
 if(x.access.military_training_completion_time_schema==0){if(f.completion_application_source)fail("UnexpectedMilitaryTrainingCompletionTime",f.id);}
 else if(f.phase==DynamicMilitaryTrainingPhase::completed)take(validate_exact_training_completion_header(common,military,state,f));
});}
