Status validate_exact_military_training_sources(const CommonStore& common,const MilitaryState& military,const MilitaryActionTimeState& state,const ActionElapsedStore& elapsed,const ExactTrainingReadContext& x,bool pending){return status([&]{
 take(validate_military_training_completion_time_layout(state,x.access.military_training_completion_time_schema));
 std::set<StableId> actions,lessons,freezes,spans,witnesses,cancellations;
 for(const auto& row:state.dynamic_training_facts.rows()){const auto& f=row.second;if(row.first!=f.id||!actions.insert(f.id).second)fail("ExactTrainingKeyMismatch",row.first);const auto* entry=find_fixed_elapsed(elapsed,f.id);if(!entry)fail("ExactTrainingElapsedRequired",f.id);take(validate_fact_history(common,military,state,x,f,*entry,pending));
  if(f.terminal_code==std::optional<StableId>{"MilitaryTrainingCancelled"}&&f.terminal_source_ref&&!cancellations.insert(f.terminal_source_ref->id).second)fail("DuplicateExactTrainingCancellation",f.id);
  for(const auto& l:f.lessons){if(!lessons.insert(l.fee_effect_ref.id).second)fail("DuplicateExactTrainingLesson",l.fee_effect_ref.id);if(l.drill_frozen_source_ref)freezes.insert(l.drill_frozen_source_ref->id);}
  const auto* unit=find(military.military_units,f.terms.unit_id);if(f.phase==DynamicMilitaryTrainingPhase::started){const auto* a=common.action(f.id);if(!a||a->kind!="military_train"||a->actor_id!=f.actor_id||a->participants!=f.terms.participants||a->start_tick!=f.started_at.half_day_tick||a->remaining_ticks!=(pending&&compare(entry->credited_units.value,entry->required_units.value,x.budget)==0?1:take(fixed_elapsed_remaining_ticks(*entry,x.scale,x.budget)))||!unit||!unit->training_action_id||*unit->training_action_id!=f.id||!unit->training||!unit->fatigue||*unit->training!=current_training(f)||*unit->fatigue!=current_fatigue(f)||reservation(common,f.terms.payer_wallet_id,f.id)!=std::optional<Integer>{military_training_progress::unprovided_fee(Integer(f.lessons.size()))})fail("ExactTrainingActiveEnvelopeMismatch",f.id);for(const auto& id:f.terms.participants){const auto* p=common.actor(id);if(!p||p->action_id!=f.id)fail("TrainingActorOccupationMissing",id);}}
  else if(common.action(f.id)||reservation(common,f.terms.payer_wallet_id,f.id)||(unit&&unit->training_action_id&&*unit->training_action_id==f.id))fail("ExactTrainingTerminalNotReleased",f.id);
 }
 for(const auto& row:state.training_participation_spans.rows())if(!actions.count(row.second.action_ref)||!spans.insert(row.first).second)fail("OrphanTrainingParticipation",row.first);
 for(const auto& row:state.training_period_witnesses.rows())if(!actions.count(row.second.action_ref)||!witnesses.insert(row.first).second)fail("OrphanTrainingPeriodWitness",row.first);
 if(freezes.size()!=state.drill_freeze_sources.rows().size())fail("OrphanTrainingDrillFreeze");for(const auto& row:state.drill_freeze_sources.rows())if(!freezes.count(row.first))fail("OrphanTrainingDrillFreeze",row.first);
 for(const auto& row:common.state().facts.rows())if(row.second.domain=="military"){
  const auto& h=row.second;if(h.kind=="military_training_completion_applied")take(validate_military_training_completion_header_source(h,military,state,x.access.military_training_completion_time_schema));
  if(h.kind=="military_training_participation"&&!spans.count(row.first))fail("MissingExactTrainingParticipation",row.first);
  if(h.kind=="military_training_period_witness"&&!witnesses.count(row.first))fail("MissingExactTrainingPeriodWitness",row.first);
  if(h.kind=="military_training_cancelled"&&!cancellations.count(row.first))fail("MissingExactTrainingCancellation",row.first);
  if(h.kind=="military_training_lesson"&&!lessons.count(row.first))fail("MissingExactTrainingLesson",row.first);
  if(h.kind=="military_training_drill_frozen"&&!freezes.count(row.first))fail("MissingExactTrainingDrillFreeze",row.first);
  if(h.kind=="military_training"&&!actions.count(row.first)&&!find(military.training_facts,row.first))fail("MissingMilitaryTrainingSource",row.first);
 }
});}
